import pytest


def fact(n: int) -> int:
    """Return n! (the factorial of n) for a non-negative integer n.

    fact(0) == 1. Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result


def test_fact_zero() -> None:
    assert fact(0) == 1


def test_fact_one() -> None:
    assert fact(1) == 1


def test_fact_small_values() -> None:
    assert fact(2) == 2
    assert fact(3) == 6
    assert fact(5) == 120
    assert fact(10) == 3628800


def test_fact_large_value() -> None:
    assert fact(20) == 2432902008176640000
    assert fact(25) == 15511210043330985984000000


def test_fact_recurrence() -> None:
    for n in range(1, 15):
        assert fact(n) == n * fact(n - 1)


def test_fact_negative() -> None:
    with pytest.raises(ValueError):
        fact(-1)
    with pytest.raises(ValueError):
        fact(-100)
